const row = $input.item.json;

const get = (...keys) => {
  for (const k of keys) {
    for (const rowKey of Object.keys(row)) {
      if (rowKey.trim().toUpperCase() === k.toUpperCase()) {
        const v = row[rowKey];
        if (v !== undefined && v !== null && String(v).trim() !== '') {
          return String(v).trim();
        }
      }
    }
  }
  return '';
};

const upcRaw = get('UPC');
const upcDigits = upcRaw.replace(/[^0-9]/g, '');
const upc = upcDigits.length === 11 ? upcDigits.padStart(12, '0') : upcDigits;

if (!upc || upc.length < 6) {
  return { json: { skip: true, upc: '', status: 'skip' } };
}

const rawBrand = get('BRAND') || get('VENDOR NAME') || 'Unbranded';
const brand = rawBrand.split('/')[0].trim() || 'Unbranded';

const productName = get('ITEM DESCRIPTION', 'PRODUCT NAME', 'DESCRIPTION');
const color       = get('COLOR');
const rawSize     = get('SIZE');
const departmentName = get('DEPARTMENT NAME', 'DEPARTMENT');

const excelCategoryId   = get('CATEGORY_ID');
const excelCategoryName = get('CATEGORY_NAME');
const excelType         = get('EBAY_TYPE');
const excelStyle        = get('EBAY_STYLE');
const excelUnderwire    = get('EBAY_UNDERWIRE');
const excelStrap        = get('EBAY_STRAP');
const excelClosure      = get('EBAY_CLOSURE');
const excelBandSize     = get('EBAY_BAND_SIZE');
const excelCupSize      = get('EBAY_CUP_SIZE');
const excelSizeClean    = get('EBAY_SIZE');
const excelDepartment   = get('EBAY_DEPARTMENT');
const excelFeatures     = get('EBAY_FEATURES');
const excelPattern      = get('EBAY_PATTERN');
const excelTheme        = get('EBAY_THEME');
const excelSetIncludes  = get('EBAY_SET_INCLUDES');

const SIZE_WORD_MAP = {
  'XXLARGE':'XXL','XX LARGE':'XXL','XXLG':'XXL','XX LG':'XXL',
  'XLARGE':'XL','X LARGE':'XL','XLRG':'XL','X LG':'XL',
  'LARGE':'L','LRG':'L','LG':'L','MEDIUM':'M','MED':'M',
  'SMALL':'S','SM':'S','XSMALL':'XS','X SMALL':'XS',
  'XXXLARGE':'3XL','XXX LARGE':'3XL','3X LARGE':'3XL','3XLARGE':'3XL',
  'ONE SIZE':'One Size','ONESIZE':'One Size'
};

let size = excelSizeClean || '';
if (!size) {
  const rawUpper = rawSize.toUpperCase().trim();
  if (SIZE_WORD_MAP[rawUpper]) {
    size = SIZE_WORD_MAP[rawUpper];
  } else {
    const braMatch = rawSize.match(/(\d{2})\s*([A-Z]{1,4})/i);
    if (braMatch) {
      size = braMatch[1] + braMatch[2].toUpperCase();
    } else {
      size = rawSize.replace(/\([^)]*\)/g, '').replace(/\s+/g,'').toUpperCase().trim();
    }
  }
}

const COLOR_MAP = {
  black:'Black',white:'White',beige:'Beige',nude:'Beige',cream:'Ivory',
  grey:'Gray',gray:'Gray',silver:'Silver',red:'Red',darkred:'Red',
  wine:'Red',pink:'Pink',rose:'Pink',coral:'Pink',blush:'Pink',
  mauve:'Pink',cerise:'Pink',blue:'Blue',navy:'Blue',royal:'Blue',
  denim:'Blue',cobalt:'Blue',green:'Green',mint:'Green',sage:'Green',
  olive:'Green',teal:'Green',purple:'Purple',lavender:'Purple',
  plum:'Purple',burgundy:'Purple',violet:'Purple',brown:'Brown',
  tan:'Brown',camel:'Brown',mocha:'Brown',chocolate:'Brown',
  yellow:'Yellow',gold:'Gold',mustard:'Yellow',orange:'Orange',
  ivory:'Ivory',champagne:'Ivory',natural:'Ivory',ecru:'Ivory',
  multi:'Multicolor',multicolor:'Multicolor',print:'Multicolor',
  floral:'Multicolor',taupe:'Taupe',heather:'Gray'
};

const WALMART_COLORS = [
  'Beige','Black','Blue','Brown','Gray','Green','Gold',
  'Ivory','Multicolor','Orange','Pink','Purple','Red',
  'Silver','White','Yellow','Taupe'
];

const colorLower = (color || '').toLowerCase().replace(/[\s\-]/g, '');
let normalizedColor = WALMART_COLORS.find(c => colorLower.includes(c.toLowerCase()));
if (!normalizedColor) {
  for (const [key, val] of Object.entries(COLOR_MAP)) {
    if (colorLower.includes(key)) { normalizedColor = val; break; }
  }
}
if (!normalizedColor) normalizedColor = color;

const qty      = Math.max(1, parseInt(get('ORIGINAL QTY','QUANTITY','QTY') || '1', 10) || 1);
const rawPrice = get('ebay price','LISTING PRICE','PRICE','ORIGINAL RETAIL');
const price    = parseFloat(String(rawPrice).replace(/[$,]/g, '').trim()) || 0;
const styleNumber = get('VENDOR/STYLE','VENDOR / STYLE #','VENDOR/STYLE #','STYLE #','MPN');
const imageUrl = get('IMAGE URL','IMAGE','PHOTO').trim();
const dept     = (excelCategoryName || departmentName || '').toUpperCase().trim();
const hint     = `${productName} ${dept} ${brand}`.toLowerCase().trim();

return {
  json: {
    sku: upc, upc, upc_raw: upcRaw, upc_digits: upcDigits,
    brand, product_name: productName,
    color_raw: color, color: normalizedColor,
    size, qty, price,
    style_number: styleNumber || upc,
    image_url: imageUrl,
    department_name: departmentName,
    dept, category_hint: hint,
    excel_category_id:   excelCategoryId,
    excel_category_name: excelCategoryName,
    excel_type:          excelType,
    excel_style:         excelStyle,
    excel_underwire:     excelUnderwire,
    excel_strap:         excelStrap,
    excel_closure:       excelClosure,
    excel_band_size:     excelBandSize,
    excel_cup_size:      excelCupSize,
    excel_department:    excelDepartment || 'Women',
    excel_features:      excelFeatures,
    excel_pattern:       excelPattern,
    excel_theme:         excelTheme,
    excel_set_includes:  excelSetIncludes,
    status: 'pending', _error: null, missing_fields: []
  }
};

const item = $input.item.json;
if (item.skip || !item.upc) return { json: { ...item, image_urls: [], image_source: 'none' } };

const walmartToken = $('Get Walmart Token').first().json.access_token;
const ebayToken    = $('Get eBay Token').first().json.access_token;
const upc = item.upc || '';
const sku = item.sku || upc;

let image_urls = [];
let imageSource = 'none';

// ── Step 1: Walmart catalog lookup by UPC ─────────────────
if (upc && walmartToken) {
  try {
    const wResp = await this.helpers.request({
      method: 'GET',
      url: 'https://marketplace.walmartapis.com/v3/items?query=' + encodeURIComponent(upc) + '&limit=5',
      headers: {
        'Authorization': 'Bearer ' + walmartToken,
        'WM_SVC.NAME': 'Walmart Marketplace',
        'WM_QOS.CORRELATION_ID': Date.now().toString(),
        'Accept': 'application/json'
      },
      timeout: 8000
    });
    const wData = typeof wResp === 'string' ? JSON.parse(wResp) : wResp;
    const items = wData?.ItemResponse || wData?.items || [];
    const product = items[0];
    if (product) {
      const main = String(product.mainImageUrl || '').trim();
      const secondary = Array.isArray(product.productSecondaryImageURL)
        ? product.productSecondaryImageURL
        : [];
      const all = [main, ...secondary].filter(Boolean);
      image_urls = [...new Set(all)].slice(0, 12);
      if (image_urls.length > 0) imageSource = 'walmart';
    }
  } catch(e) {}
}

// ── Step 2: eBay seller inventory fallback ────────────────
if (image_urls.length === 0 && sku && ebayToken) {
  try {
    const eResp = await this.helpers.request({
      method: 'GET',
      url: 'https://api.ebay.com/sell/inventory/v1/inventory_item/' + encodeURIComponent(sku),
      headers: {
        'Authorization': 'Bearer ' + ebayToken,
        'Content-Language': 'en-US'
      },
      timeout: 8000
    });
    const eData = typeof eResp === 'string' ? JSON.parse(eResp) : eResp;
    const imgs = eData?.product?.imageUrls || [];
    if (imgs.length > 0) {
      image_urls = imgs.slice(0, 12);
      imageSource = 'ebay';
    }
  } catch(e) {}
}

// ── Step 3: Excel manifest fallback ──────────────────────
if (image_urls.length === 0) {
  const excelImg = String(item.image_url || '').trim();
  if (excelImg) {
    image_urls = [excelImg];
    imageSource = 'excel';
  }
}

return {
  json: {
    ...item,
    image_urls,
    image_source: imageSource
  }
};

const item = $input.item.json;
if (item.skip) return { json: item };

const dept = (item.dept || '').toUpperCase().trim();
const hint = (item.category_hint || '').toLowerCase();
const size = item.size || '';

// ── Map from Excel eBay category if available ─────────────
const EBAY_TO_WALMART = {
  'Bras & Bra Sets':   { productType: 'WomensBras',       categoryPath: 'Clothing/Womens Clothing/Intimates/Bras' },
  'Panties':           { productType: 'WomensPanties',     categoryPath: 'Clothing/Womens Clothing/Intimates/Panties' },
  'Shapewear':         { productType: 'WomensShapewear',   categoryPath: 'Clothing/Womens Clothing/Intimates/Shapewear' },
  'Sleepwear & Robes': { productType: 'WomensSleepwear',   categoryPath: 'Clothing/Womens Clothing/Sleepwear & Loungewear' }
};

let productType = '';
let categoryPath = '';

if (item.excel_category_name && EBAY_TO_WALMART[item.excel_category_name]) {
  const mapped = EBAY_TO_WALMART[item.excel_category_name];
  productType  = mapped.productType;
  categoryPath = mapped.categoryPath;
} else if (['PANTIES','PANTY','PB PANTIES'].includes(dept)) {
  productType = 'WomensPanties'; categoryPath = 'Clothing/Womens Clothing/Intimates/Panties';
} else if (['SHAPEWEAR','SHAPE WEAR'].includes(dept)) {
  productType = 'WomensShapewear'; categoryPath = 'Clothing/Womens Clothing/Intimates/Shapewear';
} else if (['BRAS','BRA','PB BRAS','CK INNERWEAR','COLLECTIONS','DESGNR INNRWR'].includes(dept)) {
  productType = 'WomensBras'; categoryPath = 'Clothing/Womens Clothing/Intimates/Bras';
} else if (['TRAD SLEEPWR','CC SLEEPWEAR','DRESSY SLPWR','NEOTRAD SLPWR','SLEEP','SLEEPWEAR',
            'FAMLYPJ/DSGSL','JENNI COLLECT','MB INTIM/HSRY'].includes(dept)) {
  productType = 'WomensSleepwear'; categoryPath = 'Clothing/Womens Clothing/Sleepwear & Loungewear';
} else if (hint.includes('pant') || hint.includes('thong') || hint.includes('hipster') ||
           hint.includes('cheeky') || hint.includes('boyshort')) {
  productType = 'WomensPanties'; categoryPath = 'Clothing/Womens Clothing/Intimates/Panties';
} else if (hint.includes('shape') || hint.includes('shaper') || hint.includes('girdle') ||
           hint.includes('bodysuit') || hint.includes('cincher')) {
  productType = 'WomensShapewear'; categoryPath = 'Clothing/Womens Clothing/Intimates/Shapewear';
} else if (hint.includes('sleep') || hint.includes('pajama') || hint.includes('robe') ||
           hint.includes('nightgown')) {
  productType = 'WomensSleepwear'; categoryPath = 'Clothing/Womens Clothing/Sleepwear & Loungewear';
} else {
  productType = 'WomensBras'; categoryPath = 'Clothing/Womens Clothing/Intimates/Bras';
}

const braMatch = size.match(/^(\d{2})(AA?|[A-Z]{1,4})(\+?)$/i);
const bandSize = braMatch ? braMatch[1] : item.excel_band_size || '';
const cupSize  = braMatch ? braMatch[2].toUpperCase() : item.excel_cup_size || '';

const sizeType = (/\d+W$/i.test(size) || /^[1-9]X/i.test(size)) ? 'Plus' : 'Regular';

return {
  json: {
    ...item,
    walmart_product_type: productType,
    walmart_category_path: categoryPath,
    band_size: bandSize,
    cup_size: cupSize,
    size_type: sizeType
  }
};

