const aiJson = $input.item.json;
const item   = $('Classify Walmart Category').item.json;

if (item.status === 'review_needed') return { json: item };

let aiContent = {};
try {
  const raw = aiJson?.message?.content || '';
  aiContent = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {}

const brand   = item.brand  || 'Unbranded';
const color   = item.color  || '';
const size    = item.size   || '';
const pt      = item.walmart_product_type || 'WomensBras';

let walmartTitle = aiContent.title || `${brand} ${item.product_name} ${color}`.trim();
if (size && !walmartTitle.includes(size)) {
  walmartTitle = `${walmartTitle} ${size}`.substring(0, 200).trim();
}
if (!walmartTitle.toLowerCase().includes('nwt')) {
  walmartTitle = `${walmartTitle} NWT`.substring(0, 200).trim();
}

const shortDesc = (aiContent.description || item.product_name || '')
  .replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 4000);
const longDesc = aiContent.description || item.product_name || '';

const underwireRaw  = item.excel_underwire || '';
const underwireType = underwireRaw.toLowerCase().includes('wireless') ? 'Wireless' : underwireRaw ? 'Underwire' : '';

// ── Build Walmart visible attributes by product type ──────
const visible = {
  productName:                 walmartTitle.substring(0, 200),
  shortDescription:            shortDesc,
  longDescription:             longDesc,
  brand:                       brand,
  mainImageUrl:                (item.image_urls || [])[0] || '',
  productSecondaryImageURL:    (item.image_urls || []).slice(1, 9),
  gender:                      'Female',
  color:                       color,
  colorCategory:               color,
  size:                        size,
  sizeGroup:                   item.size_type || 'Regular',
  condition:                   'New',
  isProp65WarningRequired:     'No',
  isChemicalAerosolPesticide:  'No'
};

if (item.style_number) visible.manufacturerPartNumber = item.style_number;
if (item.upc)          visible.gtin                   = item.upc;

if (pt === 'WomensBras') {
  if (item.excel_type  || 'Bra')       visible.braStyle    = item.excel_type || 'Bra';
  if (underwireType)                   visible.underwireType = underwireType;
  if (item.excel_closure)              visible.closure      = item.excel_closure;
  if (item.excel_strap)                visible.strapType    = item.excel_strap;
  if (item.band_size)                  visible.bandSize     = item.band_size;
  if (item.cup_size)                   visible.cupSize      = item.cup_size;
} else if (pt === 'WomensPanties') {
  if (item.excel_type) visible.pantiesStyle = item.excel_type;
} else if (pt === 'WomensShapewear') {
  if (item.excel_type  || item.excel_style) visible.shapewearStyle = item.excel_type || item.excel_style;
  if (item.excel_closure)                   visible.closure        = item.excel_closure;
} else if (pt === 'WomensSleepwear') {
  if (item.excel_type)         visible.sleepwearStyle = item.excel_type;
  if (item.excel_set_includes) visible.setIncludes    = item.excel_set_includes;
  if (item.excel_theme)        visible.theme          = item.excel_theme;
}

if (item.excel_style)    visible.style   = item.excel_style;
if (item.excel_pattern)  visible.pattern = item.excel_pattern;
if (item.excel_features) visible.features = item.excel_features;

// Remove empty values
for (const key of Object.keys(visible)) {
  const v = visible[key];
  if (v === '' || v === null || v === undefined || (Array.isArray(v) && v.length === 0)) {
    delete visible[key];
  }
}

return {
  json: {
    ...item,
    walmart_title:   walmartTitle,
    walmart_desc:    longDesc,
    walmart_visible: visible
  }
};

const item = $input.item.json;
if (item.status === 'review_needed') return { json: item };

const missing = [];

if (!item.sku)                                    missing.push('sku');
if (!item.price || item.price <= 0)               missing.push('price > 0');
if (!item.image_urls || item.image_urls.length === 0) missing.push('image_urls — Walmart requires at least 1 image');
if (!item.walmart_title)                          missing.push('walmart_title');
if (!item.walmart_product_type)                   missing.push('walmart_product_type');
if (!item.brand || item.brand === 'Unbranded')    missing.push('brand');
if (!item.color)                                  missing.push('color');
if (!item.size)                                   missing.push('size');

const vis = item.walmart_visible || {};
if (!vis.mainImageUrl) missing.push('mainImageUrl');

if (missing.length > 0) {
  return {
    json: {
      ...item,
      status: 'review_needed',
      missing_fields: missing,
      _error: 'Validation failed: ' + missing.join(' | ')
    }
  };
}

return { json: { ...item, status: 'approved', missing_fields: [] } };

const item  = $input.item.json;
const token = $('Get Walmart Token').first().json.access_token;
const pt    = item.walmart_product_type || 'WomensBras';
const corrId = `n8n-${item.sku}-${Date.now()}`;

const feedPayload = {
  MPItemFeedHeader: {
    version: '4.7',
    requestId: corrId,
    feedDate: new Date().toISOString().split('.')[0],
    subset: 'EXTERNAL',
    mart: 'WALMART_US',
    locale: 'en'
  },
  MPItem: [{
    Orderable: {
      sku:           item.sku,
      productName:   item.walmart_title,
      productType:   pt,
      price:         parseFloat((item.price || 0).toFixed(2)),
      currency:      'USD',
      ShippingWeight: { measure: 0.5, unit: 'lbs' },
      quantity:      item.qty || 1
    },
    Visible: {
      [pt]: item.walmart_visible
    }
  }]
};

const pricePayload = {
  sku:      item.sku,
  currency: 'USD',
  price:    parseFloat((item.price || 0).toFixed(2))
};

const inventoryPayload = {
  sku:      item.sku,
  quantity: { unit: 'EACH', amount: item.qty || 1 },
  fulfillmentLagTime: 1
};

return {
  json: {
    ...item,
    _walmart_token:     token,
    _corr_id:           corrId,
    _feed_payload:      feedPayload,
    _price_payload:     pricePayload,
    _inventory_payload: inventoryPayload
  }
};

const resp = $input.item.json;
const prep = $('Prepare Walmart Payload').item.json;

const statusCode = resp.statusCode || 0;
const body       = resp.body || {};

if (statusCode === 200 || statusCode === 201 || statusCode === 202) {
  const feedId = body.feedId || body.feed_id || '';
  return { json: { ...prep, _item_status: 'ok', _feed_id: feedId, _item_status_code: statusCode } };
}

if (statusCode === 409) {
  return { json: { ...prep, _item_status: 'conflict_ok', _feed_id: '', _item_status_code: statusCode } };
}

const errMsg = body ? JSON.stringify(body).substring(0, 300) : 'Unknown error';
return { json: { ...prep, _item_status: 'error', _error: 'Create Item failed (' + statusCode + '): ' + errMsg, status: 'api_error' } };
